                    "sql": "drop table if exists public.Easyecom_tuco_kids_customer_orders_normalised; create table public.Easyecom_tuco_kids_customer_orders_normalised as select (_airbyte_data.tat)::TIMESTAMP AS tat, (_airbyte_data.city)::VARCHAR AS city, (_airbyte_data.meta)::VARCHAR AS meta, (_airbyte_data.email)::VARCHAR AS email, (_airbyte_data.state)::VARCHAR AS state, (_airbyte_data.country)::VARCHAR AS country, (_airbyte_data.courier)::VARCHAR AS courier, (_airbyte_data.message)::VARCHAR AS message, (_airbyte_data.batch_id)::BIGINT AS batch_id, (_airbyte_data.latitude)::VARCHAR AS latitude, (_airbyte_data.order_id)::BIGINT AS order_id, (_airbyte_data.pin_code)::VARCHAR AS pin_code, (_airbyte_data.qcPassed)::INTEGER AS qcpassed, (_airbyte_data.tcs_rate)::NUMERIC AS tcs_rate, (_airbyte_data.buyer_gst)::VARCHAR AS buyer_gst, (_airbyte_data.documents)::SUPER AS documents, (_airbyte_data.longitude)::VARCHAR AS longitude, (_airbyte_data.suborders)::SUPER AS suborders, (_airbyte_data.total_tax)::NUMERIC AS total_tax, (_airbyte_data.awb_number)::VARCHAR AS awb_number, (_airbyte_data.blockSplit)::INTEGER AS blocksplit, (_airbyte_data.carrier_id)::INTEGER AS carrier_id, (_airbyte_data.invoice_id)::BIGINT AS invoice_id, (_airbyte_data.order_date)::TIMESTAMP AS order_date, (_airbyte_data.order_type)::VARCHAR AS order_type, (_airbyte_data.seller_gst)::VARCHAR AS seller_gst, (_airbyte_data.state_code)::VARCHAR AS state_code, (_airbyte_data.tcs_amount)::NUMERIC AS tcs_amount, (_airbyte_data.contact_num)::VARCHAR AS contact_num, (_airbyte_data.import_date)::TIMESTAMP AS import_date, (_airbyte_data.manifest_no)::VARCHAR AS manifest_no, (_airbyte_data.marketplace)::VARCHAR AS marketplace, (_airbyte_data.pickup_city)::VARCHAR AS pickup_city, (_airbyte_data.warehouseId)::INTEGER AS warehouseid, (_airbyte_data.billing_city)::VARCHAR AS billing_city, (_airbyte_data.billing_name)::VARCHAR AS billing_name, (_airbyte_data.company_name)::VARCHAR AS company_name, (_airbyte_data.invoice_date)::TIMESTAMP AS invoice_date, (_airbyte_data.location_key)::VARCHAR AS location_key, (_airbyte_data.order_status)::VARCHAR AS order_status, (_airbyte_data.payment_mode)::VARCHAR AS payment_mode, (_airbyte_data.pickup_state)::VARCHAR AS pickup_state, (_airbyte_data.queue_status)::INTEGER AS queue_status, (_airbyte_data.total_amount)::NUMERIC AS total_amount, (_airbyte_data.\"Package Width\")::NUMERIC AS package_width, (_airbyte_data.billing_state)::VARCHAR AS billing_state, (_airbyte_data.customer_code)::VARCHAR AS customer_code, (_airbyte_data.customer_name)::VARCHAR AS customer_name, (_airbyte_data.delivery_date)::TIMESTAMP AS delivery_date, (_airbyte_data.manifest_date)::TIMESTAMP AS manifest_date, (_airbyte_data.queue_message)::VARCHAR AS queue_message, (_airbyte_data.\"Package Height\")::NUMERIC AS package_height, (_airbyte_data.\"Package Length\")::NUMERIC AS package_length, (_airbyte_data.\"Package Weight\")::NUMERIC AS package_weight, (_airbyte_data.address_line_1)::VARCHAR AS address_line_1, (_airbyte_data.address_line_2)::VARCHAR AS address_line_2, (_airbyte_data.billing_mobile)::VARCHAR AS billing_mobile, (_airbyte_data.invoice_number)::VARCHAR AS invoice_number, (_airbyte_data.marketplace_id)::INTEGER AS marketplace_id, (_airbyte_data.order_priority)::INTEGER AS order_priority, (_airbyte_data.order_quantity)::INTEGER AS order_quantity, (_airbyte_data.order_type_key)::VARCHAR AS order_type_key, (_airbyte_data.pickup_address)::VARCHAR AS pickup_address, (_airbyte_data.pickup_country)::VARCHAR AS pickup_country, (_airbyte_data.reference_code)::VARCHAR AS reference_code, (_airbyte_data.salesmanUserId)::INTEGER AS salesmanuserid, (_airbyte_data.suborder_count)::VARCHAR AS suborder_count, (_airbyte_data.total_discount)::NUMERIC AS total_discount, (_airbyte_data.available_after)::TIMESTAMP AS available_after, (_airbyte_data.billing_country)::VARCHAR AS billing_country, (_airbyte_data.order_status_id)::INTEGER AS order_status_id, (_airbyte_data.payment_mode_id)::INTEGER AS payment_mode_id, (_airbyte_data.pickup_pin_code)::VARCHAR AS pickup_pin_code, (_airbyte_data.shipping_status)::VARCHAR AS shipping_status, (_airbyte_data.batch_created_at)::TIMESTAMP AS batch_created_at, (_airbyte_data.billing_pin_code)::VARCHAR AS billing_pin_code, (_airbyte_data.last_update_date)::TIMESTAMP AS last_update_date, (_airbyte_data.shipping_history)::SUPER AS shipping_history, (_airbyte_data.billing_address_1)::VARCHAR AS billing_address_1, (_airbyte_data.billing_address_2)::VARCHAR AS billing_address_2, (_airbyte_data.pickup_state_code)::VARCHAR AS pickup_state_code, (_airbyte_data.replacement_order)::INTEGER AS replacement_order, (_airbyte_data.billing_state_code)::VARCHAR AS billing_state_code, (_airbyte_data.collectable_amount)::NUMERIC AS collectable_amount, (_airbyte_data.fulfillable_status)::INTEGER AS fulfillable_status, (_airbyte_data.shipping_status_id)::INTEGER AS shipping_status_id, (_airbyte_data.import_warehouse_id)::INTEGER AS import_warehouse_id, (_airbyte_data.payment_gateway_name)::VARCHAR AS payment_gateway_name, (_airbyte_data.import_warehouse_name)::VARCHAR AS import_warehouse_name, (_airbyte_data.invoice_currency_code)::VARCHAR AS invoice_currency_code, (_airbyte_data.total_shipping_charge)::NUMERIC AS total_shipping_charge, (_airbyte_data.courier_aggregator_name)::VARCHAR AS courier_aggregator_name, (_airbyte_data.marketplace_invoice_num)::VARCHAR AS marketplace_invoice_num, (_airbyte_data.shipping_last_update_date)::TIMESTAMP AS shipping_last_update_date, (_airbyte_data.payment_gateway_transaction_number)::VARCHAR AS payment_gateway_transaction_number FROM ( SELECT _airbyte_data, _airbyte_emitted_at, _airbyte_ab_id, ROW_NUMBER() OVER (PARTITION BY _airbyte_data.invoice_id, _airbyte_data.order_id, _airbyte_data.marketplace_id, _airbyte_data.last_update_date ORDER BY _airbyte_emitted_at DESC) AS rn FROM public._airbyte_raw_Easyecom_Tuco_Kids_final_customer_orders ) ; DROP TABLE IF EXISTS public.tuco_kids_EasyEcom_FACT_ITEMS; CREATE TABLE public.tuco_kids_EasyEcom_FACT_ITEMS AS WITH orders AS ( SELECT order_date as test,* FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY CAST(order_id AS BIGINT), CAST(invoice_id AS BIGINT) ORDER BY last_update_date DESC) AS rw FROM public.Easyecom_tuco_kids_customer_orders_normalised c ) a WHERE rw = 1 order by order_Date desc ), first_order AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY order_date ASC) AS rw FROM public.Easyecom_tuco_kids_customer_orders_normalised c ) a WHERE rw = 1 ) SELECT s.pincode, UPPER(s.Marketplace) AS SHOP_NAME, s.carrier_id, UPPER(s.courier) AS courier, UPPER(s.customer_name) AS customer_name, s.email, s.contact_num, UPPER(s.MARKETPLACE) AS marketplace, s.MARKETPLACE_ID, s.ORDER_ID, s.suborder_id, s.invoice_id, s.marketplace_invoice_num, s.buyer_gst, s.reference_code, s.Marketplace_LineItem_ID, s.invoice_date, s.courier_aggregator_name, TRY_CAST(nullif(trim(s.manifest_date),\'\') AS TIMESTAMP) AS manifest_Date, TRY_CAST(nullif(trim(s.shipping_last_update_date),\'\') AS TIMESTAMP) AS shipping_last_update_date, TRY_CAST(CASE WHEN LOWER(s.shipping_status) = \'delivered\' THEN TRY_CAST(nullif(trim(s.shipping_last_update_date),\'\') AS TIMESTAMP) END AS TIMESTAMP) AS Delivered_Date, UPPER(s.shipping_status) AS shipping_status, s.awb, s.SKU, s.master_sku, UPPER(s.sku_type) AS sku_type, s.PRODUCT_ID, UPPER(s.PRODUCTNAME) AS PRODUCTNAME, s.CURRENCY, s.IS_REFUND, UPPER(COALESCE(s.city)) AS City, UPPER(COALESCE(s.state)) AS State, UPPER(s.order_Status) AS order_Status, s.ORDER_Date, s.SHIPPING_PRICE, s.number_of_products_in_combo, s.suborder_quantity, s.item_Status, s.shipped_quantity, s.returned_quantity, s.cancelled_quantity, s.return_sales, s.cancel_sales, s.Tax, s.suborder_mrp, UPPER(s.category) AS category, s.discount, s.selling_price, COALESCE(s.suborder_mrp, 0) * s.suborder_quantity AS mrp_sales, CASE WHEN ((COALESCE(s.suborder_mrp, 0) * s.suborder_quantity) IS NULL OR (COALESCE(s.suborder_mrp, 0) * s.suborder_quantity) < s.selling_price) THEN s.discount ELSE (COALESCE(s.suborder_mrp, 0) * s.suborder_quantity) - s.selling_price END AS Discount_MRP, s.new_customer_flag, s.new_customer_flag_month, UPPER(s.Warehouse_name) AS Warehouse_name, s.Days_in_Shipment, UPPER(s.Channel) AS Channel, UPPER(s.Payment_mode) AS Payment_mode, s.import_date, s.last_update_date, s.pickup_pincode, null picked_up_time, null intransit_time, null delivered_time, UPPER(COALESCE(fsm.product_name, UPPER(SPLIT_PART(sm.product_name, \'-\', 2)))) AS mapped_product_name, UPPER(COALESCE(fsm.category, sm.category_name)) AS mapped_Category, fsm.color, fsm.size, upper(coalesce(fsm.commonsku,s.master_sku)) as commonsku FROM ( SELECT o.PIN_CODE AS pincode, o.MARKETPLACE AS SHOP_NAME, o.carrier_id, o.courier, o.courier_aggregator_name, o.customer_name, o.email, o.contact_num, o.MARKETPLACE, o.MARKETPLACE_ID, CAST(CAST(o.ORDER_ID AS BIGINT) AS VARCHAR) AS ORDER_ID, s.suborder_id::VARCHAR AS suborder_id, CAST(CAST(o.invoice_id AS BIGINT) AS VARCHAR) AS invoice_id, o.buyer_gst, o.reference_code, o.marketplace_invoice_num, TRY_CAST(NULLIF(trim(o.INVOICE_DATE), \'\') AS TIMESTAMP) AS INVOICE_DATE, o.manifest_date, o.shipping_Last_update_date AS shipping_last_update_date, o.shipping_status, o.awb_number AS awb, s.marketplace_sku::VARCHAR AS sku, s.sku::VARCHAR AS master_sku, s.sku_type::VARCHAR AS sku_type, s.product_id::VARCHAR AS product_id, s.item_status::VARCHAR AS item_status, s.suborder_num::VARCHAR AS marketplace_lineitem_id, s.productName::VARCHAR AS productname, CASE WHEN o.pickup_country = \'India\' THEN \'INR\' END AS CURRENCY, CASE WHEN CAST(s.returned_quantity::VARCHAR AS BIGINT) > 0 THEN 1 ELSE 0 END AS IS_REFUND, UPPER(CAST(o.CITY AS VARCHAR)) AS City, UPPER(CAST(o.STATE AS VARCHAR)) AS State, o.order_status, o.ORDER_Date, COALESCE(CAST(REPLACE(s.total_shipping_charge::VARCHAR, \',\', \'\') AS DOUBLE PRECISION), 0) AS shipping_price, CAST(s.item_quantity::VARCHAR AS BIGINT) AS number_of_products_in_combo, CAST(s.suborder_quantity::VARCHAR AS BIGINT) AS suborder_quantity, CAST(s.shipped_quantity::VARCHAR AS BIGINT) AS shipped_quantity, CAST(s.returned_quantity::VARCHAR AS BIGINT) AS returned_quantity, CAST(s.cancelled_quantity::VARCHAR AS BIGINT) AS cancelled_quantity, CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN 0 ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END AS selling_price, CASE WHEN CAST(s.returned_quantity::VARCHAR AS BIGINT) > 0 THEN (CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN 0 ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) * (CAST(s.returned_quantity::VARCHAR AS BIGINT)) / (CAST(s.item_quantity::VARCHAR AS BIGINT)) END AS return_sales, CASE WHEN CAST(s.cancelled_quantity::VARCHAR AS BIGINT) > 0 THEN (CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN 0 ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) END AS cancel_sales, COALESCE(CAST(s.TAX::VARCHAR AS DOUBLE PRECISION), 0) AS Tax, CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) AS suborder_mrp, s.category::VARCHAR AS category, -1 * (COALESCE(CAST(o.total_discount AS DOUBLE PRECISION) * (CASE WHEN (CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) = 0 THEN 1 ELSE (CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) END / CASE WHEN SUM(CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) OVER (PARTITION BY CAST(o.order_id AS BIGINT)) = 0 THEN 1 ELSE SUM(CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) OVER (PARTITION BY CAST(o.order_id AS BIGINT)) END), 0)) AS discount, CASE WHEN fo.order_id = o.order_id THEN \'New\' ELSE \'Repeat\' END AS new_customer_flag, CASE WHEN DATE_TRUNC(\'month\', CAST(NULLIF(LEFT(fo.order_date, 10), \'\') AS DATE)) = DATE_TRUNC(\'month\', CAST(NULLIF(LEFT(o.order_date, 10), \'\') AS DATE)) THEN \'New\' ELSE \'Repeat\' END AS new_customer_flag_month, o.company_name AS Warehouse_Name, CAST(CASE WHEN o.shipping_STATUS IN (\'In Transit\', \'Shipment Created\') THEN DATEDIFF(day, CAST(NULLIF(LEFT(o.ORDER_Date, 10), \'\') AS DATE), CURRENT_DATE) WHEN o.shipping_STATUS IN (\'Delivered\', \'Delivered To Origin\') THEN DATEDIFF(day, CAST(NULLIF(LEFT(o.ORDER_Date, 10), \'\') AS DATE), CAST(NULLIF(LEFT(o.shipping_Last_update_date, 10), \'\') AS DATE)) END AS BIGINT) AS Days_in_Shipment, o.marketplace AS Channel, o.payment_mode, o.import_date, o.last_update_date, o.pickup_pin_code AS pickup_pincode, ROW_NUMBER() OVER (PARTITION BY s.suborder_id::VARCHAR ORDER BY o.last_update_date DESC) AS rw FROM orders o LEFT JOIN first_order fo ON fo.contact_num::varchar = o.contact_num::varchar, o.suborders s ) s left join (select * from (select product_name , color , size , marketplace , CAST(marketplace_sku AS VARCHAR) AS marketplace_sku , commonsku , category , ROW_NUMBER() OVER (PARTITION BY REPLACE(CAST(commonsku AS VARCHAR), \' \', \'\') ORDER BY LENGTH(COALESCE(CAST(commonsku AS VARCHAR), \'\')) DESC) AS rw FROM public.tuco_kids_final_sku_master ) WHERE rw = 1 ) fsm ON LOWER(REPLACE(CAST(s.master_sku AS VARCHAR), \' \', \'\')) = LOWER(REPLACE(CAST(fsm.commonsku AS VARCHAR), \' \', \'\')) LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY LOWER(REPLACE(SPLIT_PART(SKU, \'-\', 1), \' \', \'\')) ORDER BY 1) AS rw FROM public.Easyecom_Tuco_Kids_product_master ) WHERE rw = 1 ) sm ON LOWER(REPLACE(SPLIT_PART(sm.SKU, \'-\', 1), \' \', \'\')) = LOWER(REPLACE(s.master_sku, \' \', \'\')) WHERE s.rw = 1; DROP TABLE IF EXISTS public.easyecom_tuco_kids_all_returns; CREATE TABLE public.easyecom_tuco_kids_all_returns AS WITH base_returns AS ( SELECT UPPER(marketplace) AS marketplace, COALESCE(REPLACE(parent_sku, \'`\', \'\'), child_sku) AS SKU, REPLACE(awb_number, \'`\', \'\') AS AWB, created_by, Invoice_id, CASE WHEN order_date IS NULL OR order_date IN (\'\', \'0000-00-00 00:00:00\', \'0000-00-00\') THEN NULL WHEN order_date ~ \'^\\d{4}-\\d{2}-\\d{2}\' THEN LEFT(order_date, 10)::date ELSE NULL END AS Order_Date, CASE WHEN return_date IS NULL OR return_date IN (\'\', \'0000-00-00 00:00:00\', \'0000-00-00\') THEN NULL WHEN return_date ~ \'^\\d{4}-\\d{2}-\\d{2}\' THEN LEFT(return_date, 10)::date ELSE NULL END AS Return_Date, CASE WHEN Invoice_Date IS NULL OR Invoice_Date IN (\'\', \'0000-00-00 00:00:00\', \'0000-00-00\') THEN NULL WHEN Invoice_Date ~ \'^\\d{4}-\\d{2}-\\d{2}\' THEN LEFT(Invoice_Date, 10)::date ELSE NULL END AS Invoice_Date, CASE WHEN Return_Initiated_Date IS NULL OR Return_Initiated_Date IN (\'\', \'0000-00-00 00:00:00\', \'0000-00-00\') THEN NULL WHEN Return_Initiated_Date ~ \'^\\d{4}-\\d{2}-\\d{2}\' THEN LEFT(Return_Initiated_Date, 10)::date ELSE NULL END AS Return_Initiated_Date, Return_Type, REPLACE(order_number, \'`\', \'\') AS reference_code, REPLACE(Order_Item_ID, \'`\', \'\') AS saleorderitemcode, serial_number, Credit_Note_Id, Invoice_Number, Return_Quantity::BIGINT AS Returned_quantity, Initiated_Reason AS return_initiated_reason, Seller_Return_Reason, Channel_return_reason, Inventory_Status, companyProductId, Creditnote_Number, MP_Credit_Note_No, MP_Delivered_Date, COALESCE(Child_Product_Name, Parent_Product_Name) AS Product_name, CASE WHEN RTO_Delivered_Date IS NULL OR RTO_Delivered_Date IN (\'\', \'0000-00-00 00:00:00\', \'0000-00-00\') THEN NULL WHEN RTO_Delivered_Date ~ \'^\\d{4}-\\d{2}-\\d{2}\' THEN LEFT(RTO_Delivered_Date, 10)::date ELSE NULL END AS RTO_Delivered_Date, Forward_Carrier_Name, Reverse_Carrier_Name, Total_Credit_Note_Amount::DOUBLE PRECISION AS Total_return_amount FROM public.easyecom_returns_report UNION ALL SELECT UPPER(marketplace) AS marketplace, sku, REPLACE(Forward_Awb_Number, \'`\', \'\') AS AWB, created_by, Invoice_id, CASE WHEN order_date ~ \'^\\d{4}-\\d{2}-\\d{2}\' THEN LEFT(order_date, 10)::date ELSE NULL END AS order_date, NULL::DATE AS Return_Date, CASE WHEN Invoice_Date ~ \'^\\d{4}-\\d{2}-\\d{2}\' THEN LEFT(Invoice_Date, 10)::date ELSE NULL END AS Invoice_Date, CASE WHEN Return_Initiated_Date ~ \'^\\d{4}-\\d{2}-\\d{2}\' THEN LEFT(Return_Initiated_Date, 10)::date ELSE NULL END AS Return_Initiated_Date, Return_Type, REPLACE(order_number, \'`\', \'\') AS reference_code, REPLACE(Order_Item_ID, \'`\', \'\') AS saleorderitemcode, NULL::VARCHAR AS serial_number, NULL::VARCHAR AS Credit_Note_Id, Invoice_Number, Return_Quantity::BIGINT AS Returned_quantity, NULL::VARCHAR AS return_initiated_reason, NULL::VARCHAR AS Seller_Return_Reason, Channel_return_reason, NULL::VARCHAR AS Inventory_Status, companyProductId, NULL::VARCHAR AS Creditnote_Number, NULL::VARCHAR AS MP_Credit_Note_No, MP_Delivered_Date, Product_name, NULL::DATE AS RTO_Delivered_Date, Forward_Carrier_Name, Reverse_Carrier_Name, NULL AS Total_return_amount FROM public.easyecom_pending_returns_report WHERE REPLACE(Order_Item_ID, \'`\', \'\') NOT IN ( SELECT DISTINCT REPLACE(Order_Item_ID, \'`\', \'\') FROM public.easyecom_returns_report ) ), ee_ranked AS ( SELECT t._airbyte_data.reference_code::VARCHAR AS reference_code_e, t._airbyte_data.suborders[0].sku::VARCHAR AS sku_e, t._airbyte_data.shipping_last_update_date::VARCHAR AS shipping_last_update_date, _airbyte_emitted_at::timestamp::date AS airbyte_updated_date, ROW_NUMBER() OVER ( PARTITION BY t._airbyte_data.reference_code::VARCHAR, t._airbyte_data.suborders[0].sku::VARCHAR ORDER BY _airbyte_emitted_at::timestamp ASC, t._airbyte_data.shipping_last_update_date::VARCHAR ASC ) as rn FROM public._airbyte_raw_EasyEcom_tuco_kids_final_CUSTOMER_ORDERS t WHERE UPPER(t._airbyte_data.shipping_status::VARCHAR) = \'RTO INITIATED\' ), ee_final AS ( SELECT * FROM ee_ranked WHERE rn = 1 ) SELECT r.*, ee.shipping_last_update_date AS rto_initiated_date FROM base_returns r LEFT JOIN ee_final ee ON ee.reference_code_e = r.reference_code AND ee.sku_e = r.sku;",
                    "transaction": true
                }
            ) }}
